import { defineConfig, globalIgnores } from "eslint/config";
import nextVitals from "eslint-config-next/core-web-vitals";
import nextTs from "eslint-config-next/typescript";

const eslintConfig = defineConfig([
  ...nextVitals,
  ...nextTs,
  globalIgnores([
    ".next/**",
    "out/**",
    "build/**",
    "next-env.d.ts",
    "playwright-report/**",
    "test-results/**",
  ]),
]);

export default eslintConfig;

const config = {
  plugins: {
    "@tailwindcss/postcss": {},
  },
};

export default config;

/// <reference types="next" />
/// <reference types="next/image-types/global" />

// NOTE: This file should not be edited.
// It is regenerated by `next dev` / `next build`.
// see https://nextjs.org/docs/app/api-reference/config/typescript for more information.

import type { NextConfig } from "next";
import { withSentryConfig } from "@sentry/nextjs";

/**
 * Next.js 16 configuration for Fracture Recovery Companion.
 *
 * Scope for Story 1.1: Marketing shell baseline — security headers, image
 * optimization, Turbopack stub, and conditional Sentry wrapping.
 * Business-specific remote image hosts (e.g. Cloudflare Stream thumbnails)
 * are introduced by later stories that need them.
 */
const nextConfig: NextConfig = {
  reactStrictMode: true,

  images: {
    formats: ["image/avif", "image/webp"],
    deviceSizes: [640, 750, 828, 1080, 1200, 1920, 2048],
    imageSizes: [16, 32, 48, 64, 96, 128, 256, 384],
  },

  experimental: {
    optimizePackageImports: [
      "lucide-react",
      "@radix-ui/react-slot",
    ],
  },

  // Next.js 16+ default bundler - empty config silences the webpack warning
  // while keeping webpack as fallback for Sentry source-map processing.
  turbopack: {},

  poweredByHeader: false,
  compress: true,
  generateEtags: true,

  output: process.env.DOCKER_BUILD === "true" ? "standalone" : undefined,

  async headers() {
    return [
      {
        source: "/(.*)",
        headers: [
          { key: "X-DNS-Prefetch-Control", value: "on" },
          { key: "X-Content-Type-Options", value: "nosniff" },
          { key: "X-Frame-Options", value: "SAMEORIGIN" },
          { key: "X-XSS-Protection", value: "1; mode=block" },
          { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
        ],
      },
      {
        source: "/static/(.*)",
        headers: [
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
        ],
      },
      {
        source: "/_next/image(.*)",
        headers: [
          {
            key: "Cache-Control",
            value: "public, max-age=604800, stale-while-revalidate=86400",
          },
        ],
      },
    ];
  },

  webpack: (config, { dev, isServer }) => {
    if (!dev && !isServer) {
      config.optimization = {
        ...config.optimization,
        usedExports: true,
        sideEffects: true,
      };
    }
    return config;
  },
};

const sentryConfig = {
  silent: true,
  org: process.env.SENTRY_ORG,
  project: process.env.SENTRY_PROJECT,
  authToken: process.env.SENTRY_AUTH_TOKEN,
  widenClientFileUpload: true,
  hideSourceMaps: true,
  disableLogger: true,
};

// Only wrap with Sentry when a DSN is configured; keeps local dev friction-free.
export default process.env.SENTRY_DSN || process.env.NEXT_PUBLIC_SENTRY_DSN
  ? withSentryConfig(nextConfig, sentryConfig)
  : nextConfig;

/**
 * Next.js Instrumentation entry.
 * Runs once when the server starts and dispatches runtime-specific Sentry init.
 */

export async function register() {
  if (process.env.NEXT_RUNTIME === "nodejs") {
    await import("./sentry.server.config");
  }

  if (process.env.NEXT_RUNTIME === "edge") {
    await import("./sentry.edge.config");
  }
}

export const onRequestError = async (
  error: Error,
  request: {
    path: string;
    method: string;
    headers: Record<string, string>;
  },
  context: {
    routerKind: "App" | "Pages";
    routePath: string;
    routeType: "render" | "route" | "action" | "middleware";
    renderSource:
      | "react-server-components"
      | "react-server-components-payload"
      | "server-rendering";
    revalidateReason: "on-demand" | "stale" | undefined;
  }
) => {
  if (!process.env.SENTRY_DSN && !process.env.NEXT_PUBLIC_SENTRY_DSN) {
    return;
  }

  const Sentry = await import("@sentry/nextjs");
  Sentry.captureException(error, {
    extra: {
      path: request.path,
      method: request.method,
      routerKind: context.routerKind,
      routePath: context.routePath,
      routeType: context.routeType,
    },
  });
};

/**
 * Sentry Client Configuration
 * Runs whenever a user loads a page in their browser.
 * No-op if NEXT_PUBLIC_SENTRY_DSN is not configured.
 */

import * as Sentry from "@sentry/nextjs";

if (process.env.NEXT_PUBLIC_SENTRY_DSN) {
  Sentry.init({
    dsn: process.env.NEXT_PUBLIC_SENTRY_DSN,

    tracesSampleRate: process.env.NODE_ENV === "production" ? 0.1 : 1.0,
    replaysSessionSampleRate: 0.1,
    replaysOnErrorSampleRate: 1.0,

    debug: process.env.NODE_ENV === "development",
    environment: process.env.NODE_ENV,

    integrations: [
      Sentry.replayIntegration({
        maskAllText: true,
        blockAllMedia: true,
      }),
      Sentry.browserTracingIntegration({
        enableInp: true,
      }),
    ],

    beforeSend(event, hint) {
      if (process.env.NODE_ENV === "development") {
        console.log("[Sentry] Event captured (dev mode):", event);
        return null;
      }

      const error = hint.originalException;
      if (error instanceof Error) {
        if (
          error.message.includes("NetworkError") ||
          error.message.includes("Failed to fetch")
        ) {
          return null;
        }
      }

      return event;
    },
  });
}

/**
 * Sentry Server Configuration
 * Runs whenever the server handles a request.
 * No-op if neither SENTRY_DSN nor NEXT_PUBLIC_SENTRY_DSN is configured.
 */

import * as Sentry from "@sentry/nextjs";

const dsn = process.env.SENTRY_DSN || process.env.NEXT_PUBLIC_SENTRY_DSN;

if (dsn) {
  Sentry.init({
    dsn,

    tracesSampleRate: process.env.NODE_ENV === "production" ? 0.1 : 1.0,

    debug: process.env.NODE_ENV === "development",
    environment: process.env.NODE_ENV,

    spotlight: process.env.NODE_ENV === "development",

    beforeSend(event, hint) {
      if (process.env.NODE_ENV === "development") {
        console.log(
          "[Sentry Server] Event captured (dev mode):",
          event.message
        );
        return null;
      }

      const error = hint.originalException;
      if (error instanceof Error) {
        if (error.message.includes("ECONNRESET")) {
          return null;
        }
        if (
          error.message.includes("Unauthorized") ||
          error.message.includes("Not Found")
        ) {
          return null;
        }
      }

      return event;
    },

    // Prisma integration is reintroduced by Story 3.1 when the ORM lands.
  });
}

/**
 * Sentry Edge Configuration
 * Used for Edge runtime functions (middleware, Edge API routes).
 * No-op if neither SENTRY_DSN nor NEXT_PUBLIC_SENTRY_DSN is configured.
 */

import * as Sentry from "@sentry/nextjs";

const dsn = process.env.SENTRY_DSN || process.env.NEXT_PUBLIC_SENTRY_DSN;

if (dsn) {
  Sentry.init({
    dsn,

    tracesSampleRate: process.env.NODE_ENV === "production" ? 0.1 : 1.0,

    debug: process.env.NODE_ENV === "development",
    environment: process.env.NODE_ENV,

    beforeSend(event) {
      if (process.env.NODE_ENV === "development") {
        console.log(
          "[Sentry Edge] Event captured (dev mode):",
          event.message
        );
        return null;
      }
      return event;
    },
  });
}

/**
 * Playwright E2E Test Configuration
 * Story 1.1 baseline: mobile + desktop shell smoke only.
 * Visual regression and expanded matrices are added by later stories.
 */
import { defineConfig, devices } from "@playwright/test";

const baseURL = process.env.PLAYWRIGHT_TEST_BASE_URL || "http://localhost:3000";

export default defineConfig({
  testDir: "./e2e",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: process.env.CI ? 1 : undefined,
  reporter: [
    ["html", { open: "never" }],
    ["list"],
  ],

  expect: {
    timeout: 10000,
  },

  use: {
    baseURL,
    trace: "on-first-retry",
    screenshot: "only-on-failure",
    video: "retain-on-failure",
  },

  projects: [
    {
      name: "Desktop Chrome",
      use: { ...devices["Desktop Chrome"] },
    },
    {
      name: "Mobile Chrome",
      use: { ...devices["iPhone 12"] },
    },
  ],

  // Reuse existing dev server when PLAYWRIGHT_TEST_BASE_URL is set externally,
  // otherwise boot a local pnpm dev server for the test run.
  ...(process.env.PLAYWRIGHT_TEST_BASE_URL
    ? {}
    : {
        webServer: {
          command: "pnpm dev",
          url: baseURL,
          reuseExistingServer: !process.env.CI,
          timeout: 120 * 1000,
        },
      }),
});

/**
 * Prisma Client Singleton
 * Prevents connection exhaustion under Next.js dev hot-reload.
 *
 * NOTE for Story 1.1: `prisma/schema.prisma` is intentionally not present yet
 * (business models land in Story 3.1). This file is kept so later stories
 * can import `prisma` from a stable path without churning imports.
 * `PrismaClient` is only instantiated at runtime; importing this module
 * alone is a no-op until the schema is generated.
 */
import { PrismaClient } from "@prisma/client";

const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined;
};

export const prisma =
  globalForPrisma.prisma ??
  new PrismaClient({
    log:
      process.env.NODE_ENV === "development"
        ? ["query", "error", "warn"]
        : ["error"],
  });

if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = prisma;
}

export default prisma;

/**
 * React Query client factory + shared query-key registry.
 * The registry starts empty in Story 1.1 and gets populated as each
 * feature lands (programs, chat, share, etc.).
 */
import { QueryClient } from "@tanstack/react-query";

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 5 * 60 * 1000,
      gcTime: 30 * 60 * 1000,
      retry: (failureCount, error) => {
        if (error instanceof Error && "status" in error) {
          const status = (error as { status: number }).status;
          if (status >= 400 && status < 500) {
            return false;
          }
        }
        return failureCount < 3;
      },
      refetchOnWindowFocus: false,
    },
    mutations: {
      retry: 1,
    },
  },
});

export const queryKeys = {
  // Feature-specific keys will be appended here as stories land (Program, Chat, Share, Analytics).
};

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * React Query Provider
 * Per-request client instance so SSR does not leak cache across users.
 */
"use client";

import { QueryClientProvider } from "@tanstack/react-query";
import { ReactQueryDevtools } from "@tanstack/react-query-devtools";
import { useState } from "react";
import { QueryClient } from "@tanstack/react-query";

interface QueryProviderProps {
  children: React.ReactNode;
}

export function QueryProvider({ children }: QueryProviderProps) {
  const [queryClient] = useState(
    () =>
      new QueryClient({
        defaultOptions: {
          queries: {
            staleTime: 5 * 60 * 1000,
            gcTime: 30 * 60 * 1000,
            retry: (failureCount, error) => {
              if (error instanceof Error && "status" in error) {
                const status = (error as { status: number }).status;
                if (status >= 400 && status < 500) {
                  return false;
                }
              }
              return failureCount < 3;
            },
            refetchOnWindowFocus: false,
          },
          mutations: {
            retry: 1,
          },
        },
      })
  );

  return (
    <QueryClientProvider client={queryClient}>
      {children}
      <ReactQueryDevtools initialIsOpen={false} />
    </QueryClientProvider>
  );
}

/**
 * NextAuth Session Provider
 * Story 1.1 wires the provider up-front so later auth stories (Story 2.1)
 * can drop in without touching the root layout.
 */
"use client";

import { SessionProvider as NextAuthSessionProvider } from "next-auth/react";
import type { Session } from "next-auth";

interface SessionProviderProps {
  children: React.ReactNode;
  session?: Session | null;
}

export function SessionProvider({ children, session }: SessionProviderProps) {
  return (
    <NextAuthSessionProvider session={session}>
      {children}
    </NextAuthSessionProvider>
  );
}

/**
 * Root Providers composition for Fracture Recovery Companion.
 *
 * Order is intentional:
 *   SessionProvider  -> outermost, exposes auth for all client trees
 *   QueryProvider    -> depends on session for authenticated requests
 *   ThemeProvider    -> innermost wrapper, switches CSS variables
 *   Toaster          -> sibling under ThemeProvider to inherit theme
 *
 * v1 is single-locale English; no dictionary-provider is wired here
 * (lease-guard's i18n stack is explicitly out of scope — see ADR-002).
 */
"use client";

import { SessionProvider } from "./session-provider";
import { QueryProvider } from "./query-provider";
import { Toaster } from "@/components/ui/sonner";
import { ThemeProvider } from "next-themes";
import type { Session } from "next-auth";

interface ProvidersProps {
  children: React.ReactNode;
  session?: Session | null;
}

export function Providers({ children, session }: ProvidersProps) {
  return (
    <SessionProvider session={session}>
      <QueryProvider>
        <ThemeProvider
          attribute="class"
          defaultTheme="system"
          enableSystem
          disableTransitionOnChange
        >
          {children}
          <Toaster position="top-right" richColors closeButton />
        </ThemeProvider>
      </QueryProvider>
    </SessionProvider>
  );
}

export { SessionProvider } from "./session-provider";
export { QueryProvider } from "./query-provider";

// Prisma schema for Fracture Recovery Companion.
//
// Story 1.1 baseline: only the generator + datasource wiring is declared so
// `prisma generate` succeeds and `src/lib/prisma.ts` type-checks.
// Business models (User, Program, Day, ChatMessage, ShareLink, etc.)
// are introduced by Story 3.1 (Data Model Foundation) per the architecture doc.
//
// See: 技术架构详细设计.md §4 数据模型设计
//      epics.md Epic 3 - Recovery Program Foundation

generator client {
  provider = "prisma-client-js"
}

datasource db {
  // Supabase Postgres for both dev and prod - see ADR-004 in 技术架构详细设计.md
  // Local dev can also point at a Supabase branch DB.
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

