    const headerBottom = header ? header.getBoundingClientRect().bottom : null;
    const targetTop = target ? target.getBoundingClientRect().top : null;
    return { headerBottom, targetTop, overlapped: targetTop !== null && headerBottom !== null ? targetTop < headerBottom : null };
  });
  console.log(JSON.stringify(result, null, 2));
  await browser.close();
})();
